// Написан вручную (несколько ролей — генератор не умеет), не проверен на живой странице — проверить при первом /qa-regress.
// spec: .qa/e2e/specs/location-map.md
// Геолокация эмулируется; Date Now не включается; в конце шаринг выключается у всех ролей.
// Меняет предпочтения free («רוצה להכיר» → «גברים») и обязательно возвращает «נשים».
import { test, expect } from '../../fixtures';
import { setupMapUser, enableSharing, disableSharing, openMap, expectInNearby, setWantToMeet, userIdOf } from './map-helpers';

test.describe('מיקום ומפה בזמן אמת', () => {
  test.describe.configure({ timeout: 240_000 }); // две роли + ожидание опроса карты у другого (#0f19c0)
  test('nearby_live учитывает предпочтения взаимно: free «גברים» — user4 пропадает у обоих @iphone @data (#46db57 #2a31ff)', async ({ asUser }) => {
    const free = await asUser('free');
    const user4 = await asUser('user4');
    await setupMapUser(free, 'free');
    await setupMapUser(user4, 'user4');
    const freeId = userIdOf('free');
    const user4Id = userIdOf('user4');
    let prefsChanged = false;
    try {
      await enableSharing(free);
      await enableSharing(user4);
      await expectInNearby(free, user4Id, true);

      prefsChanged = true;
      await setWantToMeet(free, 'גברים');
      await openMap(free);
      // Не подходит по предпочтениям → нет ни у free, ни у user4 (описание #46db57: «ותואמים להעדפות המשתמש»; AC 2 #2a31ff).
      await expectInNearby(free, user4Id, false);
      await openMap(user4);
      await expectInNearby(user4, freeId, false);

      await setWantToMeet(free, 'נשים');
      prefsChanged = false;
      await openMap(free);
      await expectInNearby(free, user4Id, true);
    } finally {
      if (prefsChanged) await setWantToMeet(free, 'נשים');
      await disableSharing(free);
      await disableSharing(user4);
    }
    expect(prefsChanged).toBe(false);
  });
});
